<?php require dirname(__DIR__).'/app/bootstrap.php';require_admin();$error='';$tab=(string)($_GET['tab']??'sales');if(!in_array($tab,['sales','coupons','reviews','restock'],true))$tab='sales';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{
 $action=(string)($_POST['action']??'');
 if($action==='coupon'){$code=strtoupper(trim((string)($_POST['code']??'')));$kind=(string)($_POST['kind']??'');$amount=(string)($_POST['amount']??'');$min=(string)($_POST['min_spend']??'');$max=(string)($_POST['max_uses']??'');$date=(string)($_POST['expires']??'');
 $end=DateTimeImmutable::createFromFormat('!Y-m-d',$date,new DateTimeZone('Asia/Dhaka'));
 if(!preg_match('/^[A-Z0-9-]{3,40}$/D',$code)||!in_array($kind,['fixed','percent'],true)||!ctype_digit($amount)||(int)$amount<1||(int)$amount>($kind==='percent'?100:100000)||!ctype_digit($min)||(int)$min>1000000||!ctype_digit($max)||(int)$max<1||(int)$max>100000||!$end||$end->format('Y-m-d')!==$date||$end->modify('+1 day')->getTimestamp()<=time())throw new DomainException('Check the code, amount, minimum spend, usage limit and future expiry date.');
 query('INSERT INTO coupons(code,kind,amount,min_spend,max_uses,expires_at) VALUES(?,?,?,?,?,?)',[$code,$kind,(int)$amount,(int)$min,(int)$max,$end->modify('+1 day')->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s')]);
 }elseif($action==='toggle_coupon'){query('UPDATE coupons SET active=1-active WHERE id=?',[(int)($_POST['id']??0)]);
 }elseif($action==='review'){$status=(string)($_POST['status']??'');if(!in_array($status,['approved','rejected','pending'],true))throw new DomainException('Invalid review status.');query('UPDATE reviews SET status=? WHERE id=?',[$status,(int)($_POST['id']??0)]);
 }elseif($action==='restock'){$status=(string)($_POST['status']??'');if(!in_array($status,['contacted','closed','waiting'],true))throw new DomainException('Invalid request status.');query('UPDATE restock_requests SET status=? WHERE id=?',[$status,(int)($_POST['id']??0)]);
 }else throw new DomainException('Unknown action.');flash('Saved.');redirect('admin/growth.php?tab='.$tab);
 }catch(DomainException $e){$error=$e->getMessage();}catch(PDOException $e){if($e->getCode()==='23000')$error='That code already exists. Use a different code.';else throw $e;}}
render_header('Store tools',true); ?>
<main class="page"><p class="eyebrow">FLAWED / STORE TOOLS</p><h1>Grow your store.</h1><nav class="tools-nav" aria-label="Store tools"><?php foreach(['sales'=>'Sales','coupons'=>'Discount codes','reviews'=>'Reviews','restock'=>'Restock requests'] as $key=>$label):?><a href="?tab=<?=$key?>" <?=$tab===$key?'aria-current="page"':''?>><?=$label?></a><?php endforeach ?></nav><?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif ?>
<?php if($tab==='sales'):
 $summary=query("SELECT COUNT(*) AS count,COALESCE(SUM(CASE WHEN payment_status='paid' AND status<>'cancelled' THEN total ELSE 0 END),0) AS paid,SUM(status='cancelled') AS cancelled,SUM(status='delivered') AS delivered FROM orders WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)")->fetch();
 $best=query("SELECT i.product_name,SUM(i.quantity) AS units,SUM(i.quantity*i.unit_price) AS gross FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.status<>'cancelled' AND o.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY i.product_id,i.product_name ORDER BY units DESC LIMIT 10")->fetchAll();
 $sizes=query("SELECT i.size,SUM(i.quantity) AS units FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.status<>'cancelled' AND o.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY i.size ORDER BY units DESC")->fetchAll(); ?>
<h2>Last 30 days</h2><div class="stats"><div><span>Orders placed</span><strong><?=(int)$summary['count']?></strong></div><div><span>Paid order value</span><strong><?=money($summary['paid'])?></strong></div><div><span>Delivered / cancelled</span><strong><?=(int)$summary['delivered']?> / <?=(int)$summary['cancelled']?></strong></div></div><p>Paid value includes delivery and discounts; it is not profit. Product figures below exclude cancelled orders and show gross item value before discounts.</p><div class="table-wrap"><table><thead><tr><th>Top products</th><th>Units ordered</th><th>Gross item value</th></tr></thead><tbody><?php foreach($best as $row):?><tr><td><?=h($row['product_name'])?></td><td><?=(int)$row['units']?></td><td><?=money($row['gross'])?></td></tr><?php endforeach ?></tbody></table></div><h2 class="spaced">Popular sizes</h2><?php foreach($sizes as $row):?><p><?=h($row['size'])?>: <?=(int)$row['units']?> units ordered</p><?php endforeach ?><?php if(!$best):?><p>No orders in this period yet.</p><?php endif ?>
<?php elseif($tab==='coupons'):$codes=query('SELECT * FROM coupons ORDER BY id DESC LIMIT 100')->fetchAll(); ?>
<div class="checkout-layout"><section><h2>Create discount code</h2><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="coupon"><label>Code<input name="code" pattern="[A-Za-z0-9-]{3,40}" maxlength="40" required placeholder="Example: YOUR-CODE"></label><label>Discount type<select name="kind"><option value="percent">Percentage</option><option value="fixed">Fixed BDT</option></select></label><label>Amount<input type="number" name="amount" min="1" max="100000" required></label><label>Minimum product subtotal (BDT)<input type="number" name="min_spend" min="0" max="1000000" value="0" required></label><label>Maximum total uses<input type="number" name="max_uses" min="1" max="100000" required></label><label>Valid through (Dhaka date)<input type="date" name="expires" required></label><button class="button dark">CREATE CODE</button></form><p>Codes apply to products only and cannot stack. Submitted orders consume one use, including orders later cancelled. A code's terms cannot be edited after creation; disable it and create another.</p></section><aside><h2>Your codes</h2><?php foreach($codes as $c):?><article class="review-card"><h3><?=h($c['code'])?></h3><p><?=$c['kind']==='percent'?(int)$c['amount'].'%':money($c['amount'])?> off · minimum <?=money($c['min_spend'])?><br><?=(int)$c['uses']?> / <?=(int)$c['max_uses']?> uses · <?=$c['active']?'Enabled':'Disabled'?><br>Expires <?=h($c['expires_at'])?> UTC</p><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="toggle_coupon"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="button outline"><?=$c['active']?'DISABLE':'ENABLE'?></button></form></article><?php endforeach ?></aside></div>
<?php elseif($tab==='reviews'):$page=max(1,(int)($_GET['page']??1));$rows=query('SELECT r.*,p.name FROM reviews r JOIN products p ON p.id=r.product_id ORDER BY r.id DESC LIMIT 30 OFFSET '.(($page-1)*30))->fetchAll(); ?>
<h2>Review moderation</h2><p>Approve genuine, relevant feedback regardless of rating. Reject spam, abuse and exposed personal information. Only approved reviews appear publicly.</p><?php foreach($rows as $v):?><article class="review-card"><h3><?=h($v['name'])?> · <?=(int)$v['rating']?> / 5</h3><p><?=h($v['display_name'])?> · <?=h($v['status'])?></p><p><?=nl2br(h($v['body']))?></p><?php if($v['photo']):?><img src="<?=url(h($v['photo']))?>" alt="Review photo awaiting moderation" width="200" height="240" loading="lazy"><?php endif ?><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?=$v['id']?>"><label>Status<select name="status"><?php foreach(['pending','approved','rejected'] as $state):?><option <?=$v['status']===$state?'selected':''?>><?=$state?></option><?php endforeach ?></select></label><button class="button outline">SAVE MODERATION</button></form></article><?php endforeach ?><div class="pagination"><?php if($page>1):?><a href="?tab=reviews&page=<?=$page-1?>">Previous</a><?php endif ?><?php if(count($rows)===30):?><a href="?tab=reviews&page=<?=$page+1?>">Next</a><?php endif ?></div>
<?php else:$page=max(1,(int)($_GET['page']??1));$rows=query("SELECT r.*,p.name,p.active,v.stock FROM restock_requests r JOIN products p ON p.id=r.product_id LEFT JOIN variants v ON v.product_id=r.product_id AND v.size=r.size WHERE r.status='waiting' ORDER BY r.id DESC LIMIT 30 OFFSET ".(($page-1)*30))->fetchAll(); ?>
<h2>Waiting for a restock</h2><p>Contact these customers individually from your store email when stock returns, then mark them contacted. These requests do not reserve stock. Automatic customer email delivery is not connected.</p><?php foreach($rows as $v):?><article class="review-card"><h3><?=h($v['name'])?> / <?=h($v['size'])?></h3><p><?=h($v['email'])?> · <?=$v['active']&&($v['stock']===null||(int)$v['stock']>0)?'Available now':'Not available yet'?></p><a href="mailto:<?=h($v['email'])?>?subject=<?=rawurlencode('Your Flawed Urbanwear restock request')?>">Email customer</a><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="restock"><input type="hidden" name="id" value="<?=$v['id']?>"><label>Request status<select name="status"><option value="waiting">Waiting</option><option value="contacted">Contacted</option><option value="closed">Closed / withdrawn</option></select></label><button class="button outline">SAVE STATUS</button></form></article><?php endforeach ?><?php if(!$rows):?><p>No waiting requests.</p><?php endif ?><div class="pagination"><?php if($page>1):?><a href="?tab=restock&page=<?=$page-1?>">Previous</a><?php endif ?><?php if(count($rows)===30):?><a href="?tab=restock&page=<?=$page+1?>">Next</a><?php endif ?></div><?php endif ?></main><?php render_footer(); ?>
